// Kopf- und Einstellungsblock, wie OrcaSlicer/Flash Studio ihn schreibt.
const orcaGCode = `; HEADER_BLOCK_START
; generated by Orca-Flashforge 1.4.2 on 2026-11-10 at 10:12:13
; model printing time: 1h 32m 10s; total estimated time: 1h 38m 4s
; total layer number: 214
; total filament length [mm] : 12345.67
; total filament volume [cm^3] : 29.69
; total filament weight [g] : 36.81
; filament_density: 1.24
; filament_diameter: 1.75
; max_z_height: 42.80
; HEADER_BLOCK_END

; EXECUTABLE_BLOCK_START
G90
M83
G1 X10 Y10 Z0.2 E1.2
; EXECUTABLE_BLOCK_END
; filament used [mm] = 12345.67
; filament used [g] = 36.81
; CONFIG_BLOCK_START
; curr_bed_type = Textured PEI Plate
; enable_support = 0
; filament_colour = #1E90FF
; filament_settings_id = "Flashforge Generic PLA"
; filament_type = PLA
; hot_plate_temp = 60
; layer_height = 0.2
; nozzle_diameter = 0.4
; nozzle_temperature = 220
; outer_wall_speed = 200
; printer_model = Flashforge Adventurer 5M Pro
; sparse_infill_density = 15%
; textured_plate_temp = 55
; wall_loops = 2
; CONFIG_BLOCK_END
`

func near(a, b float64) bool { return math.Abs(a-b) < 0.01 }

func TestMetaGCodeOrca(t *testing.T) {
	m := metaGCode(strings.NewReader(orcaGCode))
	if !near(m.TimeSec, 3600+38*60+4) {
		t.Errorf("Druckzeit = %v", m.TimeSec)
	}
	if !near(m.FilamentM, 12.34567) || !near(m.FilamentG, 36.81) {
		t.Errorf("Filament = %v m / %v g", m.FilamentM, m.FilamentG)
	}
	if m.Layers != 214 || !near(m.LayerHeight, 0.2) || m.Infill != "15%" || m.Walls != 2 {
		t.Errorf("Schicht/Füllung: %+v", m)
	}
	if !near(m.NozzleTemp, 220) || !near(m.BedTemp, 55) { // Textured PEI Plate -> 55 °C
		t.Errorf("Temperaturen: Düse %v, Bett %v", m.NozzleTemp, m.BedTemp)
	}
	if m.FilamentType != "PLA" || m.FilamentColor != "#1E90FF" || m.Supports != "nein" {
		t.Errorf("Filament/Stützen: %+v", m)
	}
	if m.Printer != "Flashforge Adventurer 5M Pro" || m.Slicer != "Orca-Flashforge" || !near(m.SpeedMMs, 200) {
		t.Errorf("Drucker/Slicer/Speed: %q %q %v", m.Printer, m.Slicer, m.SpeedMMs)
	}
}

func TestParseDuration(t *testing.T) {
	cases := map[string]float64{"1d 2h 3m 4s": 93784, "45m 3s": 2703, "2h": 7200, "3600": 3600, "": 0}
	for in, want := range cases {
		if got := parseDuration(in); got != want {
			t.Errorf("parseDuration(%q) = %v, erwartet %v", in, got, want)
		}
	}
}

func TestMeta3MF(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "projekt.3mf")
	f, _ := os.Create(path)
	z := zip.NewWriter(f)
	w, _ := z.Create("Metadata/slice_info.config")
	w.Write([]byte(`<?xml version="1.0" encoding="UTF-8"?>
<config><plate>
  <metadata key="index" value="1"/>
  <metadata key="prediction" value="5884"/>
  <metadata key="weight" value="36.81"/>
  <filament id="1" type="PETG" color="#FF7A00FF" used_m="12.35" used_g="36.81"/>
</plate></config>`))
	ps, _ := json.Marshal(map[string]any{
		"layer_height": "0.16", "nozzle_temperature": []string{"240"}, "hot_plate_temp": []string{"70"},
		"sparse_infill_density": "20%", "wall_loops": "3", "enable_support": "1",
	})
	w, _ = z.Create("Metadata/project_settings.config")
	w.Write(ps)
	z.Close()
	f.Close()

	m := readFileMeta(path, "projekt.3mf")
	if !near(m.TimeSec, 5884) || !near(m.FilamentG, 36.81) || !near(m.FilamentM, 12.35) {
		t.Errorf("slice_info: %+v", m)
	}
	if m.FilamentType != "PETG" || m.FilamentColor != "#FF7A00" {
		t.Errorf("Filament: %q %q", m.FilamentType, m.FilamentColor)
	}
	if !near(m.LayerHeight, 0.16) || !near(m.NozzleTemp, 240) || !near(m.BedTemp, 70) || m.Infill != "20%" || m.Walls != 3 || m.Supports != "ja" {
		t.Errorf("Projekteinstellungen: %+v", m)
	}
}

func TestParseFFDetail(t *testing.T) {
	var d map[string]interface{}
	json.Unmarshal([]byte(`{"status":"printing","printProgress":0.45,"printLayer":50,"targetPrintLayer":100,
	  "printDuration":1800,"estimatedTime":3600,"rightTemp":209,"rightTargetTemp":210,"leftTemp":0,
	  "platTemp":58,"platTargetTemp":60,"printSpeedAdjust":100,"currentPrintSpeed":100,"coolingFanSpeed":80,
	  "rightFilamentType":"PLA","estimatedRightLen":12500,"estimatedRightWeight":35.5,"printFileName":"Benchy.gcode",
	  "name":"Adventurer 5M Pro","firmwareVersion":"v3.1.3","errorCode":""}`), &d)
	i := parseFFDetail(d)
	if i.State != "printing" || i.Status != "Druckt" || !near(i.Progress, 0.45) || i.Layer != 50 || i.Layers != 100 {
		t.Errorf("Status/Fortschritt: %+v", i)
	}
	if !near(i.ElapsedSec, 1800) || !near(i.RemainingSec, 3600) {
		t.Errorf("Zeiten: %v / %v", i.ElapsedSec, i.RemainingSec)
	}
	if !near(i.Nozzle, 209) || !near(i.NozzleTarget, 210) || !near(i.Bed, 58) || !near(i.FanPct, 80) {
		t.Errorf("Temperaturen/Lüfter: %+v", i)
	}
	if !near(i.FilamentM, 12.5) || !near(i.FilamentG, 35.5) || i.FilamentType != "PLA" || i.Error != "" {
		t.Errorf("Filament: %+v", i)
	}

	// Aufheizen: Status "printing", aber Düse noch kalt
	d["rightTemp"] = 120.0
	if i := parseFFDetail(d); i.State != "heating" {
		t.Errorf("Aufheizen nicht erkannt: %s", i.State)
	}
	// Leerlauf: keine Zeiten anzeigen
	d["status"] = "ready"
	if i := parseFFDetail(d); i.State != "idle" || i.RemainingSec != -1 || i.ElapsedSec != -1 {
		t.Errorf("Leerlauf: %+v", i)
	}
}
